import { useState, type MouseEvent } from 'react'
import { VIZ_CSS } from '../vlab/charts'

// Chart colour tokens (light and dark), shared with the exported HTML report.
if (typeof document !== 'undefined' && !document.getElementById('viz-css')) {
  const style = document.createElement('style')
  style.id = 'viz-css'
  style.textContent = VIZ_CSS
  document.head.appendChild(style)
}

/** Renders a report chart (trusted SVG generated by vlab/charts) with a hover tooltip from data-tip attributes. */
export function Chart({ svg, caption }: { svg: string; caption?: string }) {
  const [tip, setTip] = useState<{ text: string; x: number; y: number } | null>(null)
  function move(e: MouseEvent<HTMLDivElement>) {
    const el = (e.target as Element).closest?.('[data-tip]')
    setTip(el ? { text: el.getAttribute('data-tip') ?? '', x: e.clientX, y: e.clientY } : null)
  }
  return (
    <figure className="viz relative rounded-lg border border-stone-200 bg-white p-3 dark:border-stone-800 dark:bg-stone-900">
      <div onMouseMove={move} onMouseLeave={() => setTip(null)} dangerouslySetInnerHTML={{ __html: svg }} />
      {caption && <figcaption className="mt-1 text-xs text-stone-500">{caption}</figcaption>}
      {tip && (
        <div className="pointer-events-none fixed z-50 max-w-xs rounded bg-stone-900 px-2 py-1 text-xs text-stone-50 shadow" style={{ left: tip.x + 12, top: tip.y + 12 }}>
          {tip.text}
        </div>
      )}
    </figure>
  )
}
